// Bricks: collision + bounce + score + drawing, all in one place.
for (const brick of state.bricks) {
  if (!brick.alive) continue;

  const isHit = collides(state.ball, brick) || sweptCollides(state.ball, brick);
  if (isHit) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    // Resolution: determine which face was hit using the smallest penetration
    // or the previous position if it was a swept collision.
    const dx1 = (state.ball.x + state.ball.r) - brick.x;
    const dx2 = (brick.x + brick.w) - (state.ball.x - state.ball.r);
    const dy1 = (state.ball.y + state.ball.r) - brick.y;
    const dy2 = (brick.y + brick.h) - (state.ball.y - state.ball.r);

    const minOverlap = Math.min(dx1, dx2, dy1, dy2);

    // For swept collisions, the "overlap" might be negative or large.
    // Use previous position to disambiguate.
    let hitFace = '';
    if (state.ball.prevY + state.ball.r <= brick.y) hitFace = 'top';
    else if (state.ball.prevY - state.ball.r >= brick.y + brick.h) hitFace = 'bottom';
    else if (state.ball.prevX + state.ball.r <= brick.x) hitFace = 'left';
    else if (state.ball.prevX - state.ball.r >= brick.x + brick.w) hitFace = 'right';
    else {
      // Fallback to minOverlap for static/slow collisions
      if (minOverlap === dx1) hitFace = 'left';
      else if (minOverlap === dx2) hitFace = 'right';
      else if (minOverlap === dy1) hitFace = 'top';
      else hitFace = 'bottom';
    }

    if (hitFace === 'left') {
      state.ball.vx = -Math.abs(state.ball.vx);
      state.ball.x = brick.x - state.ball.r;
    } else if (hitFace === 'right') {
      state.ball.vx = Math.abs(state.ball.vx);
      state.ball.x = brick.x + brick.w + state.ball.r;
    } else if (hitFace === 'top') {
      state.ball.vy = -Math.abs(state.ball.vy);
      state.ball.y = brick.y - state.ball.r;
    } else if (hitFace === 'bottom') {
      state.ball.vy = Math.abs(state.ball.vy);
      state.ball.y = brick.y + brick.h + state.ball.r;
    }
    break; // Only one bounce per frame to avoid double-inversion
  }

