test('D1: Bricks should deflect the ball', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball so it's hitting the right face of the brick
  state.ball.x = brick.x + brick.w + state.ball.r - 1;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = -100;
  state.ball.vy = 0;
  state.ball.prevX = state.ball.x + 10; // coming from the right
  state.ball.prevY = state.ball.y;

  frame(mockCtx, state);

  assert.ok(state.ball.vx > 0, `Ball should bounce back (vx > 0), but got ${state.ball.vx}`);
});

test('D4: Corner hit should flip both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to hit the top-left corner
  state.ball.x = brick.x - state.ball.r + 1;
  state.ball.y = brick.y - state.ball.r + 1;
  state.ball.vx = 100;
  state.ball.vy = 100;
  state.ball.prevX = state.ball.x - 10; // coming from left
  state.ball.prevY = state.ball.y - 10; // coming from top

  frame(mockCtx, state);
  assert.ok(state.ball.vx < 0 && state.ball.vy < 0, `Ball should bounce diagonally from corner, got vx:${state.ball.vx} vy:${state.ball.vy}`);
});

