  let hitX = false;
  let hitY = false;
  let face = '';

  if (state.ball.prevY + state.ball.r <= brick.y) {
    hitY = true;
    face = 'top';
  } else if (state.ball.prevY - state.ball.r >= brick.y + brick.h) {
    hitY = true;
    face = 'bottom';
  }

  if (state.ball.prevX + state.ball.r <= brick.x) {
    hitX = true;
    face = 'left';
  } else if (state.ball.prevX - state.ball.r >= brick.x + brick.w) {
    hitX = true;
    face = 'right';
  }

  if (hitX && hitY) {
    state.ball.vx = -state.ball.vx;
    state.ball.vy = -state.ball.vy;
    // Reposition to corner
    state.ball.x = (state.ball.prevX + state.ball.r <= brick.x) ? brick.x - state.ball.r : brick.x + brick.w + state.ball.r;
    state.ball.y = (state.ball.prevY + state.ball.r <= brick.y) ? brick.y - state.ball.r : brick.y + brick.h + state.ball.r;
  } else if (face === 'left') {
    state.ball.vx = -Math.abs(state.ball.vx);
    state.ball.x = brick.x - state.ball.r;
  } else if (face === 'right') {
    state.ball.vx = Math.abs(state.ball.vx);
    state.ball.x = brick.x + brick.w + state.ball.r;
  } else if (face === 'top') {
    state.ball.vy = -Math.abs(state.ball.vy);
    state.ball.y = brick.y - state.ball.r;
  } else if (face === 'bottom') {
    state.ball.vy = Math.abs(state.ball.vy);
    state.ball.y = brick.y + brick.h + state.ball.r;
  } else {
    // fallback to minOverlap if prev pos didn't disambiguate
    const dx1 = (state.ball.x + state.ball.r) - brick.x;
    const dx2 = (brick.x + brick.w) - (state.ball.x - state.ball.r);
    const dy1 = (state.ball.y + state.ball.r) - brick.y;
    const dy2 = (brick.y + brick.h) - (state.ball.y - state.ball.r);
    const minOverlap = Math.min(dx1, dx2, dy1, dy2);
    if (minOverlap === dx1) {
      state.ball.vx = -Math.abs(state.ball.vx);
      state.ball.x = brick.x - state.ball.r;
    } else if (minOverlap === dx2) {
      state.ball.vx = Math.abs(state.ball.vx);
      state.ball.x = brick.x + brick.w + state.ball.r;
    } else if (minOverlap === dy1) {
      state.ball.vy = -Math.abs(state.ball.vy);
      state.ball.y = brick.y - state.ball.r;
    } else {
      state.ball.vy = Math.abs(state.ball.vy);
      state.ball.y = brick.y + brick.h + state.ball.r;
    }
  }
  break;
}

